const body = $json.body ?? $json;

const datasetId = String(body.dataset_id ?? '').trim();
const columnName =
  body.column_name != null
    ? String(body.column_name).trim()
    : null;

const suggestion = String(body.suggestion ?? '').trim();
const decision = String(body.decision ?? '').trim().toLowerCase();

const userOverride =
  body.user_override != null
    ? String(body.user_override).trim()
    : null;

if (!datasetId) {
  throw new Error('dataset_id is required');
}

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(datasetId)) {
  throw new Error('dataset_id must be a valid UUID');
}

if (!suggestion) {
  throw new Error('suggestion is required');
}

if (!['approve', 'ignore', 'edit'].includes(decision)) {
  throw new Error(
    'decision must be approve, ignore, or edit'
  );
}

if (decision === 'edit' && !userOverride) {
  throw new Error(
    'user_override is required when decision is edit'
  );
}

return [{
  json: {
    dataset_id: datasetId,
    column_name: columnName,
    suggestion,
    decision,
    user_override: userOverride,
    user_id: body.user_id ?? null,
    organization_id: body.organization_id ?? null
  }
}];

// Pull the original request directly from the webhook.
// This avoids losing fields after the Postgres "Ensure Table" node.

const webhook =
  $('AnalyzerOS - Cleaning Decision').first().json;

const body = webhook.body ?? webhook;

// --------------------------------------------------
// Normalize incoming values
// --------------------------------------------------

const datasetId =
  String(body.dataset_id ?? '').trim();

const columnName =
  body.column_name !== undefined &&
  body.column_name !== null
    ? String(body.column_name).trim()
    : null;

let suggestion = body.suggestion;

if (
  suggestion !== null &&
  typeof suggestion === 'object'
) {
  suggestion =
    suggestion.suggestion ??
    suggestion.description ??
    suggestion.action ??
    suggestion.details ??
    JSON.stringify(suggestion);
}

suggestion =
  String(suggestion ?? '').trim();

const decision =
  String(body.decision ?? '')
    .trim()
    .toLowerCase();

const userOverride =
  body.user_override !== undefined &&
  body.user_override !== null
    ? String(body.user_override).trim()
    : null;

const userId =
  body.user_id ?? null;

const organizationId =
  body.organization_id ?? null;

// --------------------------------------------------
// Validate
// --------------------------------------------------

if (!datasetId) {
  throw new Error(
    'dataset_id is missing from cleaning request'
  );
}

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(datasetId)) {
  throw new Error(
    `Invalid dataset_id received: ${datasetId}`
  );
}

if (!suggestion) {
  throw new Error(
    'suggestion is missing from cleaning request'
  );
}

if (
  !['approve', 'ignore', 'edit'].includes(decision)
) {
  throw new Error(
    `Invalid decision: ${decision}`
  );
}

if (
  decision === 'edit' &&
  !userOverride
) {
  throw new Error(
    'user_override is required for edit'
  );
}

// --------------------------------------------------
// SQL helper
// --------------------------------------------------

function q(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return 'NULL';
  }

  return `'${String(value).replace(/'/g, "''")}'`;
}

// --------------------------------------------------
// Build INSERT
// --------------------------------------------------

const sql = `
INSERT INTO public.analyzeros_cleaning_decisions (
  dataset_id,
  organization_id,
  user_id,
  column_name,
  suggestion,
  decision,
  user_override,
  status
)
VALUES (
  ${q(datasetId)}::uuid,
  ${q(organizationId)},
  ${q(userId)},
  ${q(columnName)},
  ${q(suggestion)},
  ${q(decision)},
  ${q(userOverride)},
  'recorded'
)
RETURNING
  id::text,
  dataset_id::text,
  organization_id,
  user_id,
  column_name,
  suggestion,
  decision,
  user_override,
  status,
  created_at;
`;

return [{
  json: {
    success: true,

    dataset_id: datasetId,
    column_name: columnName,
    suggestion,
    decision,
    user_override: userOverride,

    sql
  }
}];

const saved = $json;

return [{
  json: {
    success: true,

    decision: {
      id: saved.id ?? null,
      dataset_id: saved.dataset_id,
      column_name: saved.column_name ?? null,
      suggestion: saved.suggestion,
      decision: saved.decision,
      user_override: saved.user_override ?? null,
      status: saved.status ?? 'recorded',
      created_at:
        saved.created_at ?? new Date().toISOString()
    },

    message:
      saved.decision === 'approve'
        ? 'Cleaning recommendation approved.'
        : saved.decision === 'ignore'
        ? 'Cleaning recommendation ignored.'
        : 'Cleaning recommendation updated.',

    dataset_refresh_required: false
  }
}];

const webhook = $('AnalyzerOS - Cleaning Decision').first().json;
const body = webhook.body ?? webhook;
const decision = String(body.decision ?? '').trim().toLowerCase();
const actionType = String(body.action_type ?? body.transformation?.action_type ?? body.transformation?.type ?? '').trim().toLowerCase();

const executableTypes = [
  'text_to_numeric','text_to_boolean','text_to_date',
  'trim_strings','normalize_nulls','replace_null','map_categories'
];

let route = 'semantic';
if (decision === 'ignore') route = 'ignore';
else if (executableTypes.includes(actionType)) route = 'execute';

return [{
  json: {
    dataset_id: body.dataset_id,
    column_name: body.column_name ?? null,
    suggestion: body.suggestion ?? '',
    decision,
    user_override: body.user_override ?? null,
    action_type: actionType || 'semantic_interpretation',
    params: body.transformation?.params ?? body.params ?? {},
    route
  }
}];

const d = $json;

function ident(name) {
  if (!name || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
    throw new Error(`Unsafe or invalid column_name: ${name}`);
  }
  return `"${name.replace(/"/g, '""')}"`;
}
function q(v) {
  if (v === null || v === undefined) return 'NULL';
  return `'${String(v).replace(/'/g, "''")}'`;
}

if (!d.dataset_id) throw new Error('dataset_id is required');
if (!d.column_name) throw new Error('column_name is required');

const col = ident(d.column_name);
const datasetId = q(d.dataset_id);
const key = q(d.column_name);
const params = d.params ?? {};
let expr = null;

switch (d.action_type) {
  case 'text_to_numeric':
    expr = `CASE
      WHEN NULLIF(TRIM(clean_data->>${key}), '') ~ '^[-+]?(\\d+\\.?\\d*|\\.\\d+)$'
      THEN to_jsonb((clean_data->>${key})::numeric)
      ELSE clean_data->${key}
    END`;
    break;

  case 'text_to_boolean':
    expr = `CASE
      WHEN LOWER(TRIM(clean_data->>${key})) IN ('true','t','yes','y','1') THEN 'true'::jsonb
      WHEN LOWER(TRIM(clean_data->>${key})) IN ('false','f','no','n','0') THEN 'false'::jsonb
      ELSE clean_data->${key}
    END`;
    break;

  case 'text_to_date':
    expr = `CASE
      WHEN NULLIF(TRIM(clean_data->>${key}), '') IS NULL THEN 'null'::jsonb
      ELSE to_jsonb(TRIM(clean_data->>${key}))
    END`;
    break;

  case 'trim_strings':
    expr = `CASE
      WHEN jsonb_typeof(clean_data->${key}) = 'string'
      THEN to_jsonb(TRIM(clean_data->>${key}))
      ELSE clean_data->${key}
    END`;
    break;

  case 'normalize_nulls':
    expr = `CASE
      WHEN LOWER(TRIM(COALESCE(clean_data->>${key}, ''))) IN ('','null','none','n/a','na','nan','undefined')
      THEN 'null'::jsonb
      ELSE clean_data->${key}
    END`;
    break;

  case 'replace_null':
    if (!Object.prototype.hasOwnProperty.call(params, 'value')) {
      throw new Error('replace_null requires params.value');
    }
    expr = `CASE
      WHEN clean_data->${key} IS NULL OR clean_data->${key} = 'null'::jsonb
      THEN ${q(JSON.stringify(params.value))}::jsonb
      ELSE clean_data->${key}
    END`;
    break;

  case 'map_categories':
    if (!params.mapping || typeof params.mapping !== 'object' || Array.isArray(params.mapping)) {
      throw new Error('map_categories requires params.mapping');
    }
    const cases = Object.entries(params.mapping)
      .map(([from, to]) => `WHEN clean_data->>${key} = ${q(from)} THEN ${q(JSON.stringify(to))}::jsonb`)
      .join('\n');
    expr = `CASE ${cases} ELSE clean_data->${key} END`;
    break;

  default:
    throw new Error(`Unsupported action_type: ${d.action_type}`);
}

const sql = `
UPDATE public.dealos_dataset_rows
SET clean_data = jsonb_set(
  clean_data,
  ARRAY[${key}],
  ${expr},
  true
)
WHERE dataset_id = ${datasetId}::uuid;
`;

return [{ json: { ...d, transformation_sql: sql } }];

const d = $('Route Cleaning Decision').first().json;
function q(v){ if(v===null||v===undefined) return 'NULL'; return `'${String(v).replace(/'/g,"''")}'`; }

if (!d.column_name) return [{json:{...d,reprofile_sql:null}}];

const sql = `
WITH stats AS (
  SELECT
    COUNT(*)::int AS row_count,
    COUNT(*) FILTER (
      WHERE clean_data->${q(d.column_name)} IS NULL
         OR clean_data->${q(d.column_name)} = 'null'::jsonb
    )::int AS null_count
  FROM public.dealos_dataset_rows
  WHERE dataset_id = ${q(d.dataset_id)}::uuid
)
UPDATE public.dealos_dataset_columns c
SET null_pct =
  CASE WHEN stats.row_count = 0 THEN 0
       ELSE ROUND((stats.null_count::numeric * 100.0 / stats.row_count), 2)
  END
FROM stats
WHERE c.dataset_id = ${q(d.dataset_id)}::uuid
  AND c.column_name = ${q(d.column_name)};
`;

return [{json:{...d,reprofile_sql:sql}}];

const d=$json;
function q(v){ if(v===null||v===undefined) return 'NULL'; return `'${String(v).replace(/'/g,"''")}'`; }

const interpretation = d.user_override || d.suggestion || 'Approved semantic interpretation';

const sql = `
CREATE TABLE IF NOT EXISTS public.analyzeros_dataset_interpretations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  dataset_id uuid NOT NULL REFERENCES public.dealos_datasets(id) ON DELETE CASCADE,
  column_name text,
  interpretation text NOT NULL,
  action_type text,
  source_decision text,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO public.analyzeros_dataset_interpretations (
  dataset_id,column_name,interpretation,action_type,source_decision
)
VALUES (
  ${q(d.dataset_id)}::uuid,
  ${q(d.column_name)},
  ${q(interpretation)},
  ${q(d.action_type)},
  ${q(d.decision)}
);
`;

return [{json:{...d,semantic_sql:sql,interpretation}}];

const d = $('Route Cleaning Decision').first().json;
let message = 'Cleaning decision recorded.';
let applied = false;

if (d.route === 'ignore') message = 'Cleaning recommendation ignored.';
else if (d.route === 'semantic') message = 'Semantic interpretation saved for future analysis.';
else if (d.route === 'execute') {
  message = 'Approved cleaning transformation applied.';
  applied = true;
}

return [{
  json: {
    success: true,
    dataset_id: d.dataset_id,
    column_name: d.column_name,
    decision: d.decision,
    action_type: d.action_type,
    route: d.route,
    transformation_applied: applied,
    dataset_refresh_required: applied,
    message
  }
}];
